#include <stdio.h>
#include <stdlib.h>

int cmp_asc(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);       /* 避免相减溢出 */
}

int main(void) {
    int a[7] = {5, 2, 8, 1, 9, 3, 7};
    qsort(a, 7, sizeof(int), cmp_asc);
    for (int i = 0; i < 7; i++) printf("%d%c", a[i], i == 6 ? '\n' : ' ');
    return 0;
}
